import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { cache } from 'react'
import { BackButton } from '@/components/BackButton'
import type { Comment, Post } from '@/types/post'

// Revalidate prerendered posts at most every 5 minutes
export const revalidate = 300

// Posts not returned by generateStaticParams are rendered on demand
// (replaces `fallback: 'blocking'`)
export const dynamicParams = true

interface PostWithComments {
  post: Post
  comments: Comment[]
}

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

// Memoized so generateMetadata and the page share a single fetch per request
const getPostWithComments = cache(
  async (id: string): Promise<PostWithComments | null> => {
    try {
      const [postRes, commentsRes] = await Promise.all([
        fetch(`https://jsonplaceholder.typicode.com/posts/${id}`),
        fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`),
      ])

      if (!postRes.ok || !commentsRes.ok) {
        return null
      }

      const [post, comments]: [Post, Comment[]] = await Promise.all([
        postRes.json(),
        commentsRes.json(),
      ])

      return { post, comments }
    } catch {
      return null
    }
  }
)

export async function generateMetadata({
  params,
}: PageProps<'/blog/[id]'>): Promise<Metadata> {
  const { id } = await params
  const data = await getPostWithComments(id)

  if (!data) {
    return {}
  }

  const description = data.post.body.substring(0, 160)

  return {
    title: data.post.title,
    description,
    openGraph: {
      title: data.post.title,
      description,
    },
  }
}

export default async function BlogPost({ params }: PageProps<'/blog/[id]'>) {
  const { id } = await params
  const data = await getPostWithComments(id)

  if (!data) {
    notFound()
  }

  const { post, comments } = data

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

