'use client'

import { useEffect } from 'react'

export interface ErrorViewProps {
  error: unknown
  retry: () => void
}

// Errors thrown in Server Components reach the client with a `digest`
function isServerError(error: unknown): boolean {
  return error instanceof Error && 'digest' in error && Boolean(error.digest)
}

export function ErrorView({ error, retry }: ErrorViewProps) {
  useEffect(() => {
    console.error(error)
  }, [error])

  const serverError = isServerError(error)

  return (
    <div className="error-page">
      <title>Error - My Blog</title>
      <h1>
        {serverError
          ? 'An error occurred on server'
          : 'An error occurred on client'}
      </h1>
      <p>Sorry, something went wrong.</p>
      <button onClick={() => retry()}>Try again</button>
    </div>
  )
}

